 async function loadNotices(refresh=false){
   if(!noticeApi){notify('공고 수집 서버를 연결해야 새 목록을 불러올 수 있어요.');return}
   if(noticeRequest.current)return;
   const controller=new AbortController();noticeRequest.current=controller;
   setNoticeLoading(true);setNoticeSync('LH 공고 확인 중…');
   try{
     const payload=await fetchNoticeSnapshot(noticeApi,refresh,{signal:controller.signal});
     if(controller.signal.aborted)return;
     if(payload.status==='error')throw Error('collection_failed');
     lastNoticeSuccess.current=payload.lastCheckedAt;
     setCollectedNotices(payload.items);setNoticeHealth(payload.status);setLiveNotices(cleanNotices(payload.items));setNoticeCheckedAt(payload.lastCheckedAt);
     setNoticeSync(payload.status==='stale'?'갱신 실패 · 마지막 성공 목록을 표시해요.':payload.unknownDeadlineCount?`마감일 확인이 필요한 ${payload.unknownDeadlineCount}건은 제외했어요.`:'');
     if(refresh)notify(payload.status==='ok'?`${cleanNotices(payload.items).length}개 공고를 확인했어요.`:'갱신에 실패해 마지막 성공 목록을 표시해요.');
   }catch(error){
     if(controller.signal.aborted)return;
     const stale=!!lastNoticeSuccess.current;
     setNoticeHealth(stale?'stale':'error');
     setNoticeSync(stale?'갱신 실패 · 마지막 성공 목록을 표시해요.':'공고를 불러오지 못했어요. 새로고침으로 다시 시도해주세요.');
     if(refresh)notify(error.name==='AbortError'?'수집 응답 시간이 초과됐어요. 다시 시도해주세요.':'공고 수집에 실패했어요. 다시 시도해주세요.');
   }finally{if(noticeRequest.current===controller){noticeRequest.current=null;setNoticeLoading(false)}}
 }
